// Verifies the HMAC Convex put on the raw request body, rejects stale
// timestamps (replay), and drops events this workflow already handled.
const crypto = require('crypto');
const secret = $env.CONVEX_TO_N8N_SECRET;
if (!secret) throw new Error('CONVEX_TO_N8N_SECRET is not set');

const item = $input.first();
const headers = item.json.headers || {};
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || '');
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');

const fresh = /^\d+$/.test(timestamp) && Math.abs(Date.now() / 1000 - Number(timestamp)) <= 300;
const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest();
const given = /^[0-9a-f]{64}$/i.test(signature) ? Buffer.from(signature, 'hex') : Buffer.alloc(0);
const valid = fresh && given.length === expected.length && crypto.timingSafeEqual(given, expected);
if (!valid) return [{ json: { valid: false } }];

const payload = JSON.parse(raw);
// Remember recent idempotency keys so a Convex retry after a lost response
// does not notify the same person twice. Static data persists for active workflows.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const duplicate = Boolean(store.seen[payload.idempotencyKey]);
const cutoff = Date.now() - 7 * 24 * 3600 * 1000;
for (const [key, at] of Object.entries(store.seen)) if (at < cutoff) delete store.seen[key];
store.seen[payload.idempotencyKey] = Date.now();

return [{ json: { valid: true, duplicate, payload } }];

// Mock delivery: logs the message instead of emailing. Swap this node for
// Send Email / Slack / Discord with an n8n credential to go live.
// Uses only the fields it needs: recipient name + email, tool, dates, status.
const { valid, duplicate, payload } = $input.first().json;
if (duplicate) return [{ json: { delivered: false, reason: 'duplicate', key: payload.idempotencyKey } }];

const { recipient, toolName, status, startDate, endDate } = payload;
const lines = {
  pending: `New request to borrow your ${toolName} (${startDate} to ${endDate}).`,
  approved: `Good news: your request for the ${toolName} was approved (${startDate} to ${endDate}). Pickup details are in the LendLoop app.`,
  declined: `Your request for the ${toolName} was declined.`,
  cancelled: status === 'cancelled' && recipient.role === 'owner'
    ? `A request for your ${toolName} was cancelled.`
    : `Your request for the ${toolName} was cancelled.`,
  returned: `Thanks! The ${toolName} was marked as returned.`,
};
const message = { to: recipient.email, subject: `LendLoop: ${toolName}`, text: `Hi ${recipient.name}, ${lines[status] || `Update on the ${toolName}: ${status}.`}` };
console.log('[LendLoop notification]', JSON.stringify(message));
return [{ json: { delivered: true, key: payload.idempotencyKey, message } }];
